files.src/courseboard/labels.py:
def seat_label(remaining):
    if remaining == 0:
        return "Full"
    return f"{remaining} seats available"

files.tests/test_seat_label.py:
from courseboard.labels import seat_label

def test_zero():
    assert seat_label(0) == "Full"

def test_one():
    assert seat_label(1) == "1 seats available"

def test_five():
    assert seat_label(5) == "5 seats available"

